const lessons=[{"sentences":[{"speaker":"A","text":"Hello Maria, we really need to plan our weekly language exchange session before classes start tomorrow.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.615833333333334},{"speaker":"B","text":"Hi David, I am completely ready because I brought my notebook with several interesting conversation topics.","position":2,"audioStartSeconds":6.815833333333333,"audioEndSeconds":13.328583333333333},{"speaker":"A","text":"That is wonderful since splitting our time equally ensures that both of us improve our fluency.","position":3,"audioStartSeconds":13.528583333333334,"audioEndSeconds":19.328333333333333},{"speaker":"B","text":"We should definitely spend thirty minutes practicing Spanish and another thirty minutes practicing English.","position":4,"audioStartSeconds":19.528333333333332,"audioEndSeconds":25.598666666666666},{"speaker":"A","text":"If we set a timer on my phone, nobody will accidentally talk for too long.","position":5,"audioStartSeconds":25.798666666666666,"audioEndSeconds":30.979041666666667},{"speaker":"B","text":"That brilliant rule prevents one person from dominating the entire discussion every single time.","position":6,"audioStartSeconds":31.179041666666667,"audioEndSeconds":37.32595833333333},{"speaker":"A","text":"Should we start with Spanish today because my vocabulary feels slightly rusty this morning?","position":7,"audioStartSeconds":37.525958333333335,"audioEndSeconds":43.13166666666667},{"speaker":"B","text":"Although I wanted to begin with English, starting with Spanish sounds like a very helpful compromise.","position":8,"audioStartSeconds":43.33166666666666,"audioEndSeconds":49.375458333333334},{"speaker":"A","text":"Thank you for being so flexible while we organize this schedule together today.","position":9,"audioStartSeconds":49.57545833333333,"audioEndSeconds":54.3435},{"speaker":"B","text":"No problem at all because helping each other succeed is the main goal of our partnership.","position":10,"audioStartSeconds":54.5435,"audioEndSeconds":59.89145833333333},{"speaker":"A","text":"Let us also agree to write down any difficult new words while our partner is speaking.","position":11,"audioStartSeconds":60.091458333333335,"audioEndSeconds":65.34916666666666},{"speaker":"B","text":"Reviewing those vocabulary notes at the end will make our study sessions much more productive.","position":12,"audioStartSeconds":65.54916666666666,"audioEndSeconds":71.348125},{"speaker":"A","text":"Shall we meet at the campus library every Tuesday afternoon at three oclock?","position":13,"audioStartSeconds":71.548125,"audioEndSeconds":76.25175},{"speaker":"B","text":"Tuesday at three oclock works perfectly for my schedule this semester.","position":14,"audioStartSeconds":76.45175,"audioEndSeconds":81.07804166666666},{"speaker":"A","text":"I will quickly send you a calendar invitation so neither of us forgets.","position":15,"audioStartSeconds":81.27804166666667,"audioEndSeconds":86.06408333333333},{"speaker":"B","text":"Please do that, and I will bring the coffee for our break.","position":16,"audioStartSeconds":86.26408333333333,"audioEndSeconds":90.16158333333334}],"questions":[{"prompt":"What is the primary purpose of the conversation?","options":["To plan a weekly language exchange session.","To complain about difficult university classes.","To organize a weekend coffee meeting."],"answer":"A","evidenceSentence":1,"evidence":"plan our weekly language exchange session","explanation":"Hai người đang bàn về việc lên kế hoạch cho buổi trao đổi ngôn ngữ hàng tuần."},{"prompt":"What detail does Maria mention about her preparation?","options":["She brought a notebook with conversation topics.","She translated a long article into Spanish.","She finished all her homework early."],"answer":"A","evidenceSentence":2,"evidence":"brought my notebook with several interesting conversation topics","explanation":"Maria mang theo một cuốn sổ có các chủ đề trò chuyện thú vị."},{"prompt":"Why do they decide to set a timer on the phone?","options":["To finish the meeting as quickly as possible.","To ensure nobody talks for too long.","To remind them when the library closes."],"answer":"B","evidenceSentence":5,"evidence":"nobody will accidentally talk for too long","explanation":"Họ đặt hẹn giờ để không ai nói quá lâu, đảm bảo thời gian công bằng."},{"prompt":"Which language do they agree to practice first?","options":["French.","English.","Spanish."],"answer":"C","evidenceSentence":8,"evidence":"starting with Spanish sounds like a very helpful compromise","explanation":"Họ đồng ý bắt đầu bằng tiếng Tây Ban Nha theo đề xuất của David."},{"prompt":"What extra activity do they agree to do while listening?","options":["Record the conversation on a voice recorder.","Write down difficult new words.","Draw pictures of new vocabulary items."],"answer":"B","evidenceSentence":11,"evidence":"write down any difficult new words while our partner is speaking","explanation":"Họ đồng ý ghi lại những từ mới khó trong lúc người kia đang nói."},{"prompt":"What action will David take next?","options":["Send a calendar invitation.","Buy snacks for the library.","Call the university professor."],"answer":"A","evidenceSentence":15,"evidence":"send you a calendar invitation","explanation":"David sẽ gửi lời mời lịch trực tuyến để không ai quên."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
